import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import { FaCalendarAlt, FaCheck, FaTimes, FaPlus, FaSync } from 'react-icons/fa';
import axios from 'axios';
import toast from 'react-hot-toast';

const DailyTracker = () => {
    const { user, token } = useAuth();
    const [tasks, setTasks] = useState([]);
    const [selectedDay, setSelectedDay] = useState(null);
    const [loading, setLoading] = useState(true);
    const [creating, setCreating] = useState(false);

    const today = new Date();
    const currentMonth = today.getMonth();
    const currentYear = today.getFullYear();
    const currentDay = today.getDate();

    useEffect(() => {
        if (user) {
            console.log('👤 User:', user);
            fetchTasks();
        }
    }, [user]);

    const fetchTasks = async () => {
        try {
            console.log('🔍 Fetching tasks for user:', user.id);
            const response = await axios.get(
                `http://localhost:8081/api/tasks/user/${user.id}`,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('📊 Tasks:', response.data);
            setTasks(response.data);
            setLoading(false);
        } catch (error) {
            console.error('❌ Error:', error);
            toast.error('Failed to load tasks');
            setLoading(false);
        }
    };

    const createTaskForDay = async (day) => {
        setCreating(true);
        try {
            const date = new Date(currentYear, currentMonth, day);
            const dateStr = date.toISOString().split('T')[0];
            
            console.log('📝 Creating task for day:', day, 'date:', dateStr);
            
            const response = await axios.post(
                `http://localhost:8081/api/tasks/user/${user.id}/day/${day}?date=${dateStr}`,
                {},
                { headers: { Authorization: `Bearer ${token}` } }
            );
            console.log('✅ Task created:', response.data);
            setTasks([...tasks, response.data]);
            toast.success(`Tasks created for Day ${day}`);
            return response.data;
        } catch (error) {
            console.error('❌ Error creating task:', error);
            toast.error('Failed to create tasks');
            return null;
        } finally {
            setCreating(false);
        }
    };

    const toggleTask = async (taskId, field) => {
        const task = tasks.find(t => t.id === taskId);
        if (!task) return;

        const updatedTask = { ...task, [field]: !task[field] };
        
        try {
            const response = await axios.put(
                `http://localhost:8081/api/tasks/${taskId}`,
                updatedTask,
                { headers: { Authorization: `Bearer ${token}` } }
            );
            setTasks(tasks.map(t => t.id === taskId ? response.data : t));
            toast.success('✅ Updated!');
        } catch (error) {
            toast.error('Failed to update');
        }
    };

    const handleDayClick = async (day) => {
        console.log('📅 Day clicked:', day);
        setSelectedDay(day);
        const dayTasks = tasks.filter(task => task.day === day);
        console.log('📋 Existing tasks for day:', dayTasks);
        if (dayTasks.length === 0 && !creating) {
            await createTaskForDay(day);
        }
    };

    const getDayTasks = (day) => tasks.filter(task => task.day === day);

    const getDayStatus = (day) => {
        const dayTasks = getDayTasks(day);
        if (dayTasks.length === 0) return 'empty';
        const completed = dayTasks.filter(t => t.overallCompleted).length;
        if (completed === dayTasks.length) return 'done';
        if (completed > 0) return 'partial';
        return 'started';
    };

    if (loading) {
        return (
            <div className="d-flex justify-content-center align-items-center" style={{ height: '60vh' }}>
                <div className="spinner-border text-primary" role="status">
                    <span className="visually-hidden">Loading...</span>
                </div>
            </div>
        );
    }

    const taskLabels = [
        { key: 'javaCompleted', label: '☕ Java (1.5h)', icon: '📚' },
        { key: 'leetcodeCompleted', label: '💻 LeetCode (1+)', icon: '🎯' },
        { key: 'dsaCompleted', label: '📊 DSA/OOP (1h)', icon: '🧩' },
        { key: 'sqlCompleted', label: '🗄️ SQL/APIs (1h)', icon: '🔗' },
        { key: 'projectCompleted', label: '🚀 Project (2-3h)', icon: '⚡' },
        { key: 'githubCompleted', label: '📁 GitHub/Portfolio', icon: '📝' }
    ];

    const daysInMonth = new Date(currentYear, currentMonth + 1, 0).getDate();
    const monthNames = ['January', 'February', 'March', 'April', 'May', 'June', 
                        'July', 'August', 'September', 'October', 'November', 'December'];
    const weekDays = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'];

    return (
        <div className="container-fluid p-0">
            {/* Header */}
            <div className="bg-white rounded-4 shadow-sm p-4 mb-4">
                <div className="d-flex justify-content-between align-items-center flex-wrap">
                    <div>
                        <h4 className="fw-bold mb-0">
                            <FaCalendarAlt className="text-primary me-2" />
                            {monthNames[currentMonth]} {currentYear}
                        </h4>
                        <div className="text-muted small">
                            Today: <strong>{currentDay} {monthNames[currentMonth]}</strong>
                        </div>
                    </div>
                    <button onClick={fetchTasks} className="btn btn-outline-secondary btn-sm rounded-pill px-3">
                        <FaSync className="me-1" /> Refresh
                    </button>
                </div>
            </div>

            <div className="row g-4">
                {/* Calendar */}
                <div className="col-lg-8">
                    <div className="bg-white rounded-4 shadow-sm p-4">
                        <div className="row g-1">
                            {weekDays.map(day => (
                                <div key={day} className="col text-center text-muted small fw-semibold py-1">
                                    {day}
                                </div>
                            ))}
                            {Array.from({ length: daysInMonth }, (_, i) => i + 1).map((day) => {
                                const status = getDayStatus(day);
                                let bgColor = 'bg-light';
                                let textColor = 'text-dark';
                                
                                if (status === 'done') bgColor = 'bg-success text-white';
                                else if (status === 'partial') bgColor = 'bg-warning text-white';
                                else if (status === 'started') bgColor = 'bg-primary text-white';
                                
                                const isSelected = selectedDay === day;
                                const isToday = day === currentDay && currentMonth === new Date().getMonth();
                                
                                return (
                                    <div key={day} className="col p-1">
                                        <button
                                            onClick={() => handleDayClick(day)}
                                            className={`w-100 btn ${bgColor} ${textColor} rounded-3 fw-semibold ${isSelected ? 'ring-2 ring-primary' : ''}`}
                                            style={{ aspectRatio: '1/1', fontSize: '14px', padding: '4px', position: 'relative' }}
                                        >
                                            {day}
                                            {isToday && (
                                                <span className="position-absolute top-0 start-100 translate-middle p-1 bg-danger rounded-circle" style={{ width: '8px', height: '8px' }} />
                                            )}
                                        </button>
                                    </div>
                                );
                            })}
                        </div>
                    </div>
                </div>

                {/* Task List */}
                <div className="col-lg-4">
                    <div className="bg-white rounded-4 shadow-sm p-4" style={{ minHeight: '400px' }}>
                        <h6 className="fw-bold mb-3">
                            {selectedDay ? `📋 Day ${selectedDay} Tasks` : 'Select a day'}
                        </h6>
                        
                        {selectedDay ? (
                            <div className="d-flex flex-column gap-2">
                                {taskLabels.map(({ key, label, icon }) => {
                                    const dayTasks = getDayTasks(selectedDay);
                                    const task = dayTasks[0];
                                    const isCompleted = task ? task[key] : false;
                                    
                                    return (
                                        <div
                                            key={key}
                                            className={`d-flex justify-content-between align-items-center p-2 rounded-3 ${
                                                isCompleted ? 'bg-success bg-opacity-10' : 'bg-light'
                                            }`}
                                        >
                                            <div className="d-flex align-items-center gap-2">
                                                <span>{icon}</span>
                                                <span className={`small ${isCompleted ? 'text-muted text-decoration-line-through' : ''}`}>
                                                    {label}
                                                </span>
                                            </div>
                                            <button
                                                onClick={() => task && toggleTask(task.id, key)}
                                                className={`btn btn-sm rounded-circle p-1 ${
                                                    isCompleted ? 'btn-success' : 'btn-outline-secondary'
                                                }`}
                                                style={{ width: '28px', height: '28px' }}
                                            >
                                                {isCompleted ? <FaCheck size={12} /> : <FaTimes size={12} />}
                                            </button>
                                        </div>
                                    );
                                })}
                                
                                {getDayTasks(selectedDay).length === 0 && !creating && (
                                    <div className="text-center py-4">
                                        <p className="text-muted small mb-3">No tasks for this day</p>
                                        <button
                                            onClick={() => handleDayClick(selectedDay)}
                                            className="btn btn-primary rounded-pill px-4"
                                        >
                                            <FaPlus className="me-2" /> Create Tasks
                                        </button>
                                    </div>
                                )}
                                
                                {creating && (
                                    <div className="text-center py-4">
                                        <div className="spinner-border text-primary" role="status" />
                                        <p className="text-muted small mt-2">Creating tasks...</p>
                                    </div>
                                )}
                            </div>
                        ) : (
                            <div className="d-flex align-items-center justify-content-center py-5 text-muted">
                                <p className="small">👆 Click a day on the calendar</p>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
};

export default DailyTracker;
